quota_scripts.script:
function httpErr(e) {
  var m = e && e.message ? String(e.message) : String(e);
  if (m.indexOf("HTTP ") === 0) return m;
  if (m.indexOf("JSON parse: ") === 0) return "Parse: " + m.slice(12);
  return "Network: " + m;
}
function num(v) {
  if (typeof v === "number") return v;
  if (typeof v === "string" && v.trim() !== "" && !isNaN(Number(v))) return Number(v);
  return 0.0;
}
var body;
try {
  body = http.get("https://api.stepfun.com/v1/accounts", { Authorization: "Bearer " + ctx.apiKey });
} catch (e) {
  return { success: false, error: httpErr(e) };
}
if (body == null) body = {};
return {
  success: true,
  error: null,
  balance: {
    remaining: num(body.balance),
    total: null,
    used: null,
    currency: "CNY",
    is_valid: true
  },
  coding_plan: null
};
